"""Original fog_shS GLSL, adapted for MusiK live oscilloscope deformation.

Source: user-provided Code/Fog/fog_shS.py, same fog and bloom style.
"""

FULLSCREEN_VERTEX = '\n#version 330\n\nout vec2 uv;\n\nvoid main()\n{\n    vec2 verts[3] = vec2[](\n        vec2(-1.0, -1.0),\n        vec2( 3.0, -1.0),\n        vec2(-1.0,  3.0)\n    );\n\n    vec2 p = verts[gl_VertexID];\n\n    uv = p * 0.5 + 0.5;\n\n    gl_Position = vec4(\n        p,\n        0.0,\n        1.0\n    );\n}\n'

FOG_FRAGMENT = '\n#version 330\n\nuniform float u_time;\nuniform float u_density;\nuniform vec2 u_resolution;\n\nin vec2 uv;\n\nout vec4 fragColor;\n\n\nfloat hash21(vec2 p)\n{\n    p = fract(\n        p * vec2(\n            123.34,\n            456.21\n        )\n    );\n\n    p += dot(\n        p,\n        p + 45.32\n    );\n\n    return fract(\n        p.x * p.y\n    );\n}\n\n\nfloat noise(vec2 p)\n{\n    vec2 i = floor(p);\n    vec2 f = fract(p);\n\n    f =\n        f * f *\n        (3.0 - 2.0 * f);\n\n    float a = hash21(i);\n\n    float b = hash21(\n        i + vec2(1, 0)\n    );\n\n    float c = hash21(\n        i + vec2(0, 1)\n    );\n\n    float d = hash21(\n        i + vec2(1, 1)\n    );\n\n    return mix(\n        mix(a, b, f.x),\n        mix(c, d, f.x),\n        f.y\n    );\n}\n\n\nfloat fbm(vec2 p)\n{\n    float value = 0.0;\n    float amp = 0.5;\n\n    mat2 rot = mat2(\n         0.80, 0.60,\n        -0.60, 0.80\n    );\n\n    for (\n        int i = 0;\n        i < 4;\n        i++\n    )\n    {\n        value += (\n            amp * noise(p)\n        );\n\n        p = rot * p;\n\n        p *= 2.03;\n\n        p += vec2(\n            17.1,\n            9.2\n        );\n\n        amp *= 0.5;\n    }\n\n    return value;\n}\n\n\nfloat fog_layer(\n    vec2 p,\n    float scale,\n    vec2 drift,\n    float seed\n)\n{\n    float t = u_time;\n\n    p *= scale;\n\n    p += drift * t;\n\n    vec2 warp;\n\n    warp.x = fbm(\n        p * 0.72 +\n        vec2(\n            seed + t * 0.018,\n            seed * 2.1 - t * 0.012\n        )\n    );\n\n    warp.y = fbm(\n        p * 0.72 +\n        vec2(\n            seed * 3.7 - t * 0.014,\n            seed + 5.2 + t * 0.017\n        )\n    );\n\n    warp -= 0.5;\n\n    p += warp * 2.2;\n\n    float cloud = fbm(\n        p +\n        vec2(\n            t * 0.009,\n            -t * 0.015\n        )\n    );\n\n    float envelope = fbm(\n        p * 0.31 +\n        vec2(\n            seed * 5.1,\n            t * 0.006\n        )\n    );\n\n    float density = smoothstep(\n        0.42,\n        0.72,\n        cloud\n    );\n\n    density *= smoothstep(\n        0.16,\n        0.68,\n        envelope\n    );\n\n    return pow(\n        density,\n        1.10\n    );\n}\n\n\nvoid main()\n{\n    vec2 p =\n        (\n            gl_FragCoord.xy -\n            u_resolution * 0.5\n        )\n        /\n        u_resolution.y;\n\n    p.y *= 0.82;\n\n\n    float fog1 = fog_layer(\n        p + vec2(-0.20, 0.05),\n        1.15,\n        vec2(0.020, 0.002),\n        1.7\n    );\n\n    float fog2 = fog_layer(\n        p + vec2(0.30, -0.12),\n        1.75,\n        vec2(-0.013, 0.005),\n        7.2\n    );\n\n    float fog3 = fog_layer(\n        p + vec2(-0.10, 0.18),\n        2.55,\n        vec2(0.008, -0.004),\n        13.4\n    );\n\n\n    vec3 color =\n        vec3(\n            0.010,\n            0.012,\n            0.016\n        );\n\n\n    float a1 =\n        fog1 *\n        0.33 *\n        u_density;\n\n    float a2 =\n        fog2 *\n        0.24 *\n        u_density;\n\n    float a3 =\n        fog3 *\n        0.16 *\n        u_density;\n\n\n    // Vaaleammat, melko neutraalit harmaat\n    vec3 fog_color1 =\n        vec3(\n            0.72,\n            0.73,\n            0.75\n        );\n\n    vec3 fog_color2 =\n        vec3(\n            0.78,\n            0.79,\n            0.81\n        );\n\n    vec3 fog_color3 =\n        vec3(\n            0.84,\n            0.85,\n            0.87\n        );\n\n\n    color = mix(\n        color,\n        fog_color1,\n        clamp(\n            a1,\n            0.0,\n            0.42\n        )\n    );\n\n    color = mix(\n        color,\n        fog_color2,\n        clamp(\n            a2,\n            0.0,\n            0.32\n        )\n    );\n\n    color = mix(\n        color,\n        fog_color3,\n        clamp(\n            a3,\n            0.0,\n            0.24\n        )\n    );\n\n\n    float vignette =\n        smoothstep(\n            0.48,\n            1.10,\n            length(p)\n        );\n\n    color *= (\n        1.0 -\n        vignette * 0.30\n    );\n\n\n    fragColor = vec4(\n        color,\n        1.0\n    );\n}\n'

TEXT_FRAGMENT = '\n#version 330\n\nuniform float u_time;\nuniform float u_beat;\n\nuniform vec3 u_camera_pos;\nuniform vec3 u_light_pos;\n\nin vec3 world_pos;\nin vec3 normal;\n\nout vec4 fragColor;\n\n\nvoid main()\n{\n    vec3 N =\n        normalize(normal);\n\n    vec3 L =\n        normalize(\n            u_light_pos -\n            world_pos\n        );\n\n    vec3 V =\n        normalize(\n            u_camera_pos -\n            world_pos\n        );\n\n    vec3 H =\n        normalize(\n            L + V\n        );\n\n\n    float diffuse =\n        max(\n            dot(N, L),\n            0.0\n        );\n\n\n    float specular =\n        pow(\n            max(\n                dot(N, H),\n                0.0\n            ),\n            90.0\n        );\n\n\n    float fresnel =\n        pow(\n            1.0 -\n            abs(\n                dot(N, V)\n            ),\n            2.3\n        );\n\n\n    float pulse =\n        0.5 +\n        0.5 *\n        sin(\n            u_time * 2.0\n        );\n\n\n    // Tummansininen runko\n    vec3 base =\n        vec3(\n            0.008,\n            0.025,\n            0.10\n        );\n\n\n    // Kirkas sähkönsininen\n    vec3 blue =\n        vec3(\n            0.04,\n            0.32,\n            1.00\n        );\n\n\n    // UV-henkinen vaaleansininen\n    vec3 electric =\n        vec3(\n            0.15,\n            0.72,\n            1.00\n        );\n\n\n    vec3 color =\n        base * 0.50;\n\n\n    color +=\n        blue *\n        (\n            0.24 +\n            diffuse * 0.70\n        );\n\n\n    color +=\n        vec3(\n            0.70,\n            0.88,\n            1.00\n        )\n        *\n        specular\n        *\n        (1.25 + 0.45 * u_beat);\n\n\n    color +=\n        electric\n        *\n        fresnel\n        *\n        (\n            0.65 +\n            pulse * 0.20\n        );\n\n\n    // Pieni oma emissive hohto jo itse pinnassa\n    color +=\n        electric *\n        (\n            0.10 +\n            pulse * 0.05\n        );\n\n\n    fragColor =\n        vec4(\n            color,\n            1.0\n        );\n}\n'

GLOW_FRAGMENT = '\n#version 330\n\nuniform float u_time;\nuniform float u_beat;\nuniform vec3 u_camera_pos;\n\nin vec3 world_pos;\nin vec3 normal;\n\nout vec4 fragColor;\n\n\nvoid main()\n{\n    vec3 N =\n        normalize(normal);\n\n    vec3 V =\n        normalize(\n            u_camera_pos -\n            world_pos\n        );\n\n\n    float edge =\n        pow(\n            1.0 -\n            abs(\n                dot(\n                    N,\n                    V\n                )\n            ),\n            1.8\n        );\n\n\n    float pulse =\n        0.85 +\n        0.15 *\n        sin(\n            u_time * 2.0\n        );\n\n\n    // HDR-arvot yli 1.0 ovat tarkoituksellisia.\n    vec3 glow =\n        vec3(\n            0.08,\n            0.48,\n            1.45\n        );\n\n\n    float intensity =\n        (\n            0.60 +\n            edge * 1.8\n        )\n        *\n        pulse;\n\n\n    fragColor =\n        vec4(\n            glow * intensity * (1.0 + 0.80 * u_beat),\n            1.0\n        );\n}\n'

BLUR_FRAGMENT = '\n#version 330\n\nuniform sampler2D u_texture;\nuniform vec2 u_direction;\n\nin vec2 uv;\n\nout vec4 fragColor;\n\n\nvoid main()\n{\n    vec3 result =\n        texture(\n            u_texture,\n            uv\n        ).rgb\n        *\n        0.227027;\n\n\n    result +=\n        texture(\n            u_texture,\n            uv +\n            u_direction * 1.384615\n        ).rgb\n        *\n        0.316216;\n\n\n    result +=\n        texture(\n            u_texture,\n            uv -\n            u_direction * 1.384615\n        ).rgb\n        *\n        0.316216;\n\n\n    result +=\n        texture(\n            u_texture,\n            uv +\n            u_direction * 3.230769\n        ).rgb\n        *\n        0.070270;\n\n\n    result +=\n        texture(\n            u_texture,\n            uv -\n            u_direction * 3.230769\n        ).rgb\n        *\n        0.070270;\n\n\n    fragColor =\n        vec4(\n            result,\n            1.0\n        );\n}\n'

COMPOSITE_FRAGMENT = '\n#version 330\n\nuniform sampler2D u_scene;\nuniform sampler2D u_bloom;\n\nuniform float u_bloom_strength;\n\nin vec2 uv;\n\nout vec4 fragColor;\n\n\nvoid main()\n{\n    vec3 scene =\n        texture(\n            u_scene,\n            uv\n        ).rgb;\n\n\n    vec3 bloom =\n        texture(\n            u_bloom,\n            uv\n        ).rgb;\n\n\n    vec3 color =\n        scene +\n        bloom *\n        u_bloom_strength;\n\n\n    // Kevyt filmic tone map:\n    // estää glowta palamasta täysin valkoiseksi.\n    color =\n        color /\n        (\n            color +\n            vec3(1.0)\n        );\n\n\n    // Hieman nostetaan takaisin kirkkautta\n    color =\n        pow(\n            color,\n            vec3(0.90)\n        );\n\n\n    fragColor =\n        vec4(\n            color,\n            1.0\n        );\n}\n'

TEXT_VERTEX = r"""
#version 330
uniform mat4 u_model;
uniform mat4 u_view;
uniform mat4 u_proj;
uniform sampler2D u_audio;
uniform float u_wave_strength;
uniform float u_time;
in vec3 in_pos;
in vec3 in_normal;
in vec2 in_edge;
in vec2 in_phase_weight;
out vec3 world_pos;
out vec3 normal;
void main() {
    // The actual glyph outline vertices are the oscilloscopes. Each point
    // samples a different position in the live 512-sample waveform, then
    // moves along its local 2D outward contour normal and a little in Z.
    float waveform = texture(u_audio, vec2(fract(in_phase_weight.x), 0.5)).r;
    float offset = clamp(waveform, -1.0, 1.0) * u_wave_strength * in_phase_weight.y;
    vec3 point = in_pos + vec3(in_edge * offset,
        offset * 0.32 * sin(u_time * 1.3 + in_phase_weight.x * 29.0));
    vec4 wp = u_model * vec4(point, 1.0);
    world_pos = wp.xyz;
    normal = normalize(mat3(transpose(inverse(u_model))) * in_normal);
    gl_Position = u_proj * u_view * wp;
}
"""
